public int mystery(String text){
  Scanner sc = new Scanner(text);
  int count = 0;
  while( sc.hasNext() ){
    String temp = sc.next();
    int len = temp.length();
    if( len > 0 && temp.charAt(0) == 'A' )
      count++;
  }
  return count;
}

