    int val = 0;
    obj = obj.toLowerCase();
    for(int i = 0; i < obj.length(); i++){
      char ch = obj.charAt(i);
      if( Character.isLetter( ch ) )
        val += ch - 'a';
    }
    return val % con.length;
  }
}

